import React, { useEffect } from 'react';
import * as Sentry from '@sentry/react';
import '../App.css';
import { VideoRecorder, createDefaultTheme,loadRedHatFonts } from '@brightloop/video-recorder';
import { ThemeProvider } from '@mui/material/styles';
import { Typography } from '@mui/material';

interface UploadResponse {
  message: string;
  uuid?: string;
  busy: boolean;
  error?: boolean;
}

const redHatTheme = createDefaultTheme({
  palette: {
    primary: {
      main: '#000000',
    },
  }
});

const VideoRecorderPage: React.FC = () => {
  useEffect(() => {
    loadRedHatFonts();
  }, []);

  const handleSubmit = async (data: Blob, url: string): Promise<void> => {
    console.log("data",data, url);
    const message: UploadResponse = { message: "Please wait while the video is uploaded...", busy: true };
    window.parent.postMessage(message, '*');
    const uuid = crypto.randomUUID();

    try {
      //const presignRes = await fetch("http://localhost:3500/video/presign", {
      const presignRes = await fetch("https://video-response-upload.herokuapp.com/video/presign", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ filename: uuid + ".webm" })
      });

      if (!presignRes.ok) {
        const responseText = await presignRes.text();
        Sentry.captureException(new Error(`Presign request failed with status ${presignRes.status}`), {
          contexts: {
            upload: { uuid, blobSize: data.size, httpStatus: presignRes.status, responseBody: responseText },
          },
        });
        const errorMessage: UploadResponse = { message: "There was an error uploading your video.", busy: false, error: true };
        window.parent.postMessage(errorMessage, '*');
        return;
      }

      const { uploadUrl } = await presignRes.json();

      const uploadRes = await fetch(uploadUrl, {
        method: "PUT",
        headers: { "Content-Type": "video/webm" },
        body: data
      });

      console.log("uploadRes", uploadRes, url);

      if (uploadRes.ok) {
        const successMessage: UploadResponse = { message: "Upload complete. You may continue.", uuid: uuid, busy: false, error: false };
        window.parent.postMessage(successMessage, '*');
      } else {
        Sentry.captureException(new Error(`S3 upload failed with status ${uploadRes.status}`), {
          contexts: {
            upload: { uuid, blobSize: data.size, uploadUrl, httpStatus: uploadRes.status },
          },
        });
        const errorMessage: UploadResponse = { message: "There was an error uploading your video.", busy: false, error: true };
        window.parent.postMessage(errorMessage, '*');
      }
    } catch (error) {
      Sentry.captureException(error, {
        contexts: {
          upload: { uuid, blobSize: data.size },
        },
      });
      const errorMessage: UploadResponse = { message: "There was an error uploading your video.", busy: false, error: true };
      window.parent.postMessage(errorMessage, '*');
    }
  }

  return (
    <ThemeProvider theme={redHatTheme}> 
    <VideoRecorder
      onRecordingComplete={handleSubmit}
      maxDuration={360}
      showDownloadButton={false}
      enableBackgroundBlur={false}
      enableDeviceSelection={true}
      enableUpload={false}
      theme="redhat"
      aspectRatio={16/9}
      enableRotationCorrection={false}
      maxFileSize={300 * 1024 * 1024}
    />
    </ThemeProvider>
  );
}

export default VideoRecorderPage; 